async () => {
const c=window.phoneRinger.current(); return !!c && c.npcId==='gary_phone' && c.state==='ringing';

}

async () => {
const b = document.querySelector('.incoming-call-decline'); if (!b) return 'no decline button'; b.click(); return 'declined';

}

async () => {
const c=window.phoneRinger.current(); const m=window.MinigameFramework.currentMinigame; const l=document.getElementById('phone-ring-layer'); return {t:Math.round(performance.now()/100)/10, ringer:c?c.npcId+':'+c.state:null, mg:m?m.constructor.name+':'+(m._sceneType||''):null, layer:l?l.innerText.replace(/\n+/g,' | '):null, laptop:getComputedStyle(document.getElementById('laptop-popup')||document.body).display};

}

async () => {
window.MinigameFramework.endMinigame(false); return true;

}

async () => {
return {callback: window.phoneRinger.callbackFor('gary_phone'), rows:(window.npcManager.getConversationHistory('gary_phone')||[]).map(m=>m.type+':'+m.text)};

}

async () => {
const c=document.querySelector('.contact-item[data-npc-id="gary_phone"]'); if(!c) return 'no contact'; c.click(); return 'opened';

}

async () => {
const hb=document.querySelector('.call-button'); const m=document.querySelector('.messages-container'); return {header:hb&&hb.innerText.trim(), rowButtons:[...document.querySelectorAll('.call-row-callback')].map(b=>b.getAttribute('aria-label')), text:m&&m.innerText.replace(/\n+/g,' | '), choices:[...document.querySelectorAll('.choice-button')].map(b=>b.innerText.trim())};

}

async () => {
document.querySelector('.call-button').click(); return 'dial';

}

async () => {
const bar=document.getElementById('call-status-bar'); const subs=[...document.querySelectorAll('.call-subtitle')].map(s=>s.innerText.replace(/\n+/g,' ')); return {bar:bar?bar.innerText.replace(/\n+/g,' '):null, subs:subs.slice(-2), choices:[...document.querySelectorAll('.choice-button')].map(b=>b.innerText.trim()), end:!!document.getElementById('call-end-button')};

}

